def field(xy, p, interaction):
    (r, c) = xy.T
    d = np.minimum.reduce([r, 15 - r, c, 23 - c])
    e = np.exp(-d / np.exp(p[4]))
    illum = p[2] * (r / 15 - 0.5) + p[3] * (c / 23 - 0.5)
    return p[0] + p[1] * e + illum if not interaction else (p[0] + p[1] * e) * (1 + illum)
